import json
d = json.load(open('win_3_4/observation_00.json'))
raw = d['raw_response']

# Find the JSON block between ``` delimiters
start = raw.find('```')
end = raw.rfind('```')
if start >= 0 and end > start:
    json_str = raw[start+3:end].strip()
    # The json_str starts with "json\n{...}"
    # Remove the "json" header
    lines = json_str.split('\n')
    # Find the line that starts with {
    json_start = 0
    for i, line in enumerate(lines):
        if line.strip().startswith('{'):
            json_start = i
            break
    json_str = '\n'.join(lines[json_start:])
    try:
        parsed = json.loads(json_str)
        motion = parsed.get('result', {}).get('motion', [])
        print(json.dumps(motion, indent=2))
    except json.JSONDecodeError as e:
        print("JSON decode error:", e)
        print("Trying different approach...")
        # Find first { and last }
        first_brace = json_str.find('{')
        last_brace = json_str.rfind('}')
        if first_brace >= 0 and last_brace > first_brace:
            count = 0
            for i in range(first_brace, last_brace+1):
                if json_str[i] == '{':
                    count += 1
                elif json_str[i] == '}':
                    count -= 1
                    if count == 0:
                        extracted = json_str[first_brace:i+1]
                        parsed = json.loads(extracted)
                        motion = parsed.get('result', {}).get('motion', [])
                        print(json.dumps(motion, indent=2))
                        break
PYEOF

