# Let me validate the JSON against the schema
import json

with open('evidence-draft.json') as f:
    evidence = json.load(f)

# Check required fields
required = ['schema_version', 'sample_id', 'clip_id', 'decision', 'reported_count', 'reported_targets', 'windows_examined', 'frames_processed', 'tool_trace']
for r in required:
    if r in evidence:
        print(f"  {r}: OK")
    else:
        print(f"  {r}: MISSING")

# Check reported_targets structure
for target in evidence['reported_targets']:
    print(f"\nTarget: {target['target_ref']}")
    target_required = ['target_ref', 'color_name', 'interval_frames', 'anchors']
    for r in target_required:
        if r in target:
            print(f"  {r}: OK")
        else:
            print(f"  {r}: MISSING")

    # Check anchors
    for i, anchor in enumerate(target['anchors']):
        print(f"  Anchor {i}:")
        anchor_required = ['frame_id', 'timestamp_sec', 'roi_xyxy', 'frame_path', 'claim', 'observation_ref']
        for r in anchor_required:
            if r in anchor:
                print(f"    {r}: OK")
            else:
                print(f"    {r}: MISSING")

print("\n\nValidation complete")
PYEOF

