if d['sample_id'] != 'wrong-way-2-challenging-r1': errors.append('Wrong sample_id')
if d['clip_id'] != '2-challenging-r1': errors.append('Wrong clip_id')
if d['decision'] != 'report': errors.append('Wrong decision')
if d['reported_count'] != 1: errors.append('Wrong reported_count')
if len(d['reported_targets']) != 1: errors.append('Wrong number of targets')
