if 'white' != t['color_name']: errors.append('Wrong color_name')
if len(t['anchors']) < 2: errors.append('Need at least 2 anchors')
if len(d['windows_examined']) < 1: errors.append('Need at least 1 window')
if d['frames_processed'] <= 0: errors.append('frames_processed must be positive')
if errors:
    print('VALIDATION FAILED:')
    for e in errors: print(f'  - {e}')
